
from pathlib import Path

import pandas as pd
import plotly.express as px
import streamlit as st

st.title("Hadoop Team Analytics")
st.caption(
    "Football team statistics processed using Hadoop MapReduce and HDFS."
)

# Load the actual output generated by the Hadoop Reducer.
PROJECT_ROOT = Path(__file__).resolve().parents[1]
OUTPUT_FILE = PROJECT_ROOT / "reports" / "team_season_stats.tsv"

if not OUTPUT_FILE.exists():
    st.error(
        "Hadoop output not found. Run the MapReduce job and "
        "copy its output into reports/team_season_stats.tsv."
    )
    st.stop()

columns = [
    "season_team",
    "played",
    "wins",
    "draws",
    "losses",
    "goals_for",
    "goals_against",
    "points",
]

try:
    df = pd.read_csv(
        OUTPUT_FILE,
        sep="\t",
        header=None,
        names=columns,
    )

    # Separate the season and team from the Reducer's key.
    split_key = df["season_team"].astype(str).str.split(
        "|", n=1, regex=False, expand=True
    )

    if split_key.shape[1] != 2:
        st.error("The Hadoop output format is invalid.")
        st.stop()

    df["season"] = split_key[0]
    df["team"] = split_key[1]

    numeric_columns = [
        "played",
        "wins",
        "draws",
        "losses",
        "goals_for",
        "goals_against",
        "points",
    ]

    for column in numeric_columns:
        df[column] = pd.to_numeric(df[column], errors="coerce")

    df = df.dropna(subset=numeric_columns + ["season", "team"])

except Exception as exc:
    st.error(f"Could not read the Hadoop output: {exc}")
    st.stop()

if df.empty:
    st.warning("No team statistics are available.")
    st.stop()

seasons = sorted(df["season"].unique())
selected_season = st.selectbox("Select season", seasons)

season_df = df[df["season"] == selected_season].copy()
season_df = season_df.sort_values(
    ["points", "wins", "goals_for"],
    ascending=False,
).reset_index(drop=True)

season_df.insert(0, "Rank", range(1, len(season_df) + 1))

st.subheader(f"Team standings — {selected_season}")

c1, c2, c3, c4 = st.columns(4)
c1.metric("Teams", len(season_df))
c2.metric("Matches played by teams", int(season_df["played"].sum()))
c3.metric("Total team wins", int(season_df["wins"].sum()))
c4.metric("Total points", int(season_df["points"].sum()))

st.dataframe(
    season_df[
        [
            "Rank",
            "team",
            "played",
            "wins",
            "draws",
            "losses",
            "goals_for",
            "goals_against",
            "points",
        ]
    ],
    use_container_width=True,
    hide_index=True,
)

st.subheader("Points by team")

points_chart = px.bar(
    season_df.sort_values("points", ascending=True),
    x="points",
    y="team",
    orientation="h",
    labels={"points": "League points", "team": "Team"},
    title=f"Team points in {selected_season}",
)

st.plotly_chart(points_chart, use_container_width=True)

st.subheader("Wins, draws and losses")

results_df = season_df.melt(
    id_vars="team",
    value_vars=["wins", "draws", "losses"],
    var_name="result_type",
    value_name="matches",
)

results_chart = px.bar(
    results_df,
    x="team",
    y="matches",
    color="result_type",
    barmode="group",
    labels={
        "team": "Team",
        "matches": "Number of matches",
        "result_type": "Result",
    },
    title=f"Match outcomes in {selected_season}",
)

st.plotly_chart(results_chart, use_container_width=True)

st.subheader("Goals scored vs conceded")

goals_chart = px.scatter(
    season_df,
    x="goals_against",
    y="goals_for",
    hover_name="team",
    size="points",
    labels={
        "goals_against": "Goals conceded",
        "goals_for": "Goals scored",
        "points": "League points",
    },
    title=f"Goals comparison in {selected_season}",
)

st.plotly_chart(goals_chart, use_container_width=True)

st.caption(
    "Source: team-season statistics produced by the Hadoop MapReduce "
    "Reducer. Rankings use points, wins and goals scored as tie-breakers."
)

if len(seasons) < 5:
    st.warning(
        f"The current Hadoop output contains {len(seasons)} seasons, "
        "not all five expected seasons. Check the input results before "
        "using this output as a complete five-season analysis."
    )
